import React from 'react'
import LiteYouTubeEmbed from 'react-lite-youtube-embed';
import 'react-lite-youtube-embed/dist/LiteYouTubeEmbed.css'

function Drone() {
    return (
        <div className='portfolioContainer'>
            <Video video="https://youtu.be/75j_bwcLrRM" name="New Bern Sunset"/>
                <div className='portfolioGrid'>
                <Video video="https://youtu.be/PqHxPFT9UFs" name="Crab Island - Destin Florida"/>
                <Video video="https://youtu.be/j2r2OOAaFig" name="Destin Florida Amusement Park"/>
            </div>
        </div>
    )

    function Video(props) {
        var video = props.video.replace('https://youtu.be/','');
        return (
            <div className='videoBox'>
                <div className='videoBoxContainer'>
                    {/* <iframe width="560" height="315" src={"https://www.youtube.com/embed/" + video} title="YouTube video player" 
                    frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" 
                    allowfullscreen></iframe> */}
                    <LiteYouTubeEmbed id={video} title={props.name}/>
                    <span>{props.name}</span>
                </div>
            </div>
        )
    }

}

export default Drone
